-- Тема 05: 11 вопросов в инженерном стиле (43 исправлений), прежние версии в question_archive (миграция 104), ключи не меняются.
-- Источник: scripts/questions/105_style_topic05.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Когда строится снимок данных на уровне Repeatable Read?', NULL, NULL, NULL, 'Вы открыли транзакцию BEGIN ISOLATION LEVEL REPEATABLE READ и выполняете в ней запросы SELECT. Когда создаётся её снимок?'),
        ('question', 'Что такое горизонт очистки?', NULL, NULL, NULL, 'После массового DELETE и COMMIT часть старых версий строк осталась в таблице. Какую границу VACUUM использует, решая, что из них можно вычистить?'),
        ('question', 'На каких уровнях изоляции транзакция может завершиться ошибкой сериализации при обычных изменениях строк (без перемещения строк между секциями)?', NULL, NULL, NULL, 'Две транзакции обновляют одну и ту же строку несекционированной таблицы. На каких уровнях изоляции возможна ошибка сериализации?'),
        ('question', 'Транзакция на уровне Repeatable Read уже построила снимок. Затем другая транзакция удалила строку и зафиксировала изменение. Увидит ли первая транзакция эту строку при повторном запросе?', NULL, NULL, NULL, 'На Repeatable Read транзакция A прочитала строку id = 1 и осталась открытой. Затем B удалила эту строку и сделала COMMIT. A повторяет тот же SELECT. Вернётся ли строка?'),
        ('question', 'На каком уровне определяется горизонт очистки для обычных таблиц?', NULL, NULL, NULL, 'В db1 транзакция на Repeatable Read прочитала таблицу и осталась открытой. На каком уровне определяется удерживаемый ею горизонт очистки обычных таблиц?'),
        ('question', 'Обычная блокировка строки или таблицы была получена после установки точки сохранения. Когда она будет снята при откате к этой точке?', NULL, NULL, NULL, 'После SAVEPOINT s транзакция впервые заблокировала строку id = 1 командой UPDATE. Затем выполнила ROLLBACK TO s и осталась открытой. Когда освободится эта блокировка?'),
        ('question', 'Две транзакции без точек сохранения захватили разные строки, а затем каждая запросила блокировку строки, удерживаемой другой. Как PostgreSQL разрешает такую взаимоблокировку?', NULL, NULL, NULL, 'Две транзакции работают без точек сохранения. A обновила строку 1, B — строку 2, обе открыты. Теперь A обновляет строку 2, а B — строку 1. Что сделает PostgreSQL?'),
        ('question', 'Строка уже зафиксирована. Транзакция A изменила её командой UPDATE и ещё не завершилась. Второй сеанс работает на уровне Read Committed и обращается к этой строке обычным SELECT (без FOR UPDATE и FOR SHARE) или командой UPDATE. Что произойдёт?', NULL, NULL, NULL, 'Строка id = 1 уже зафиксирована. Транзакция A обновила её и осталась открытой. Второй сеанс на Read Committed выполняет по этому id обычный SELECT или UPDATE. Что произойдёт?'),
        ('question', 'В транзакции после SAVEPOINT s вставлена строка. Какой номер транзакции окажется в xmin этой строки?', NULL, NULL, NULL, 'После BEGIN выполнили SAVEPOINT s и INSERT INTO t VALUES (1). Чей номер записан в xmin новой строки?'),
        ('question', 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Номер в xmax оставлен удалением или изменением строки, а не её блокировкой. Какие версии строки в него попадут?', NULL, NULL, NULL, 'Транзакции из вариантов ниже уже завершились. После этого вы на Read Committed выполняете SELECT * FROM t. Какие версии строк вернёт запрос?'),
        ('question', 'Сеанс ждёт блокировку. Что верно о поиске причины ожидания и об ограничении времени ожидания?', NULL, NULL, NULL, 'Запрос ждёт блокировку. Что поможет найти блокирующий сеанс или ограничить ожидание?'),
        ('option', 'Вы открыли транзакцию BEGIN ISOLATION LEVEL REPEATABLE READ и выполняете в ней запросы SELECT. Когда создаётся её снимок?', 'В начале каждого оператора транзакции', 'В начале каждого оператора', NULL, NULL),
        ('option', 'Вы открыли транзакцию BEGIN ISOLATION LEVEL REPEATABLE READ и выполняете в ней запросы SELECT. Когда создаётся её снимок?', 'В момент фиксации транзакции', 'В момент COMMIT этой транзакции', NULL, NULL),
        ('option', 'Вы открыли транзакцию BEGIN ISOLATION LEVEL REPEATABLE READ и выполняете в ней запросы SELECT. Когда создаётся её снимок?', 'При первом операторе после BEGIN', 'При первом SELECT после BEGIN', NULL, NULL),
        ('option', 'После массового DELETE и COMMIT часть старых версий строк осталась в таблице. Какую границу VACUUM использует, решая, что из них можно вычистить?', 'Максимальный размер таблицы перед запуском очистки', 'Порог размера таблицы для запуска очистки', 'Горизонт — это номер транзакции, а не размер.', 'Размер влияет на то, когда запустится автоочистка, но не на то, какие версии можно убрать.'),
        ('option', 'После массового DELETE и COMMIT часть старых версий строк осталась в таблице. Какую границу VACUUM использует, решая, что из них можно вычистить?', 'Номер транзакции: удалённое до него не видно снимкам', 'Горизонт очистки по номерам транзакций', 'Номер транзакции, удалённые до которого версии строк уже не видны ни в одном снимке: такие версии не нужны ни одному снимку и могут быть вычищены.', 'Горизонт задаётся номером транзакции: версии, удалённые транзакциями старше горизонта, уже не нужны ни одному снимку и могут быть вычищены.'),
        ('option', 'После массового DELETE и COMMIT часть старых версий строк осталась в таблице. Какую границу VACUUM использует, решая, что из них можно вычистить?', 'Время следующего запуска автоочистки для таблицы', 'Время последнего запуска автоочистки', 'Расписание автоочистки — отдельное понятие.', 'Время запуска не говорит, нужны ли версии каким-то снимкам.'),
        ('option', 'После массового DELETE и COMMIT часть старых версий строк осталась в таблице. Какую границу VACUUM использует, решая, что из них можно вычистить?', 'Номер последней контрольной точки в журнале', 'Позицию последней контрольной точки в WAL', NULL, NULL),
        ('option', 'В db1 транзакция на Repeatable Read прочитала таблицу и осталась открытой. На каком уровне определяется удерживаемый ею горизонт очистки обычных таблиц?', 'Один на весь кластер баз данных', 'На уровне всего кластера', 'В курсе горизонт рассматривается для каждой базы отдельно.', 'Горизонт обычных таблиц считается по транзакциям своей базы: в других базах очистка работает как обычно.'),
        ('option', 'В db1 транзакция на Repeatable Read прочитала таблицу и осталась открытой. На каком уровне определяется удерживаемый ею горизонт очистки обычных таблиц?', 'Отдельно для каждого сеанса клиента', 'На уровне отдельного сеанса', 'Сеанс лишь может удерживать горизонт своей долгой транзакцией.', 'Сеанс может удерживать горизонт своей транзакцией, но отдельного горизонта для каждого сеанса нет.'),
        ('option', 'В db1 транзакция на Repeatable Read прочитала таблицу и осталась открытой. На каком уровне определяется удерживаемый ею горизонт очистки обычных таблиц?', 'Отдельно для каждой базы данных', 'На уровне базы данных db1', 'Для обычных таблиц горизонт определяется по транзакциям базы данных. Для общих и локальных каталогов и временных таблиц правила особые.', 'Горизонт обычных таблиц один на базу: пока транзакция открыта, очистка в db1 не уберёт версии, которые ещё может увидеть её снимок. Для общих каталогов кластера правила особые.'),
        ('option', 'В db1 транзакция на Repeatable Read прочитала таблицу и осталась открытой. На каком уровне определяется удерживаемый ею горизонт очистки обычных таблиц?', 'Отдельно для каждой таблицы базы', 'На уровне отдельной таблицы', 'Горизонт определяется по транзакциям базы, а не по таблице.', 'Горизонт обычных таблиц учитывает транзакции базы, а не список таблиц, которые они успели прочитать.'),
        ('explanation', 'В db1 транзакция на Repeatable Read прочитала таблицу и осталась открытой. На каком уровне определяется удерживаемый ею горизонт очистки обычных таблиц?', NULL, NULL, 'Версии, удалённые транзакциями до горизонта, уже не видны ни в одном снимке и могут быть вычищены.', 'Горизонт очистки для обычных таблиц свой у каждой базы: долгая транзакция в одной базе не мешает очистке в другой. Версии, удалённые до горизонта, уже не видны ни в одном снимке и могут быть вычищены.'),
        ('option', 'После SAVEPOINT s транзакция впервые заблокировала строку id = 1 командой UPDATE. Затем выполнила ROLLBACK TO s и осталась открытой. Когда освободится эта блокировка?', 'Через deadlock_timeout после отката к точке', 'После истечения deadlock_timeout', NULL, NULL),
        ('option', 'После SAVEPOINT s транзакция впервые заблокировала строку id = 1 командой UPDATE. Затем выполнила ROLLBACK TO s и осталась открытой. Когда освободится эта блокировка?', 'Её нужно снять вручную командой администратора', 'После вмешательства администратора', 'Все блокировки снимаются автоматически.', 'Эту блокировку снимает откат к точке s, администратор не нужен.'),
        ('option', 'После SAVEPOINT s транзакция впервые заблокировала строку id = 1 командой UPDATE. Затем выполнила ROLLBACK TO s и осталась открытой. Когда освободится эта блокировка?', 'Сразу при откате к этой точке сохранения', 'При откате к точке сохранения s', 'Так блокировки, полученные после точки сохранения, освобождаются раньше конца транзакции.', 'Откат к точке сохранения отменяет подтранзакцию, и её блокировки освобождаются сразу.'),
        ('option', 'После SAVEPOINT s транзакция впервые заблокировала строку id = 1 командой UPDATE. Затем выполнила ROLLBACK TO s и осталась открытой. Когда освободится эта блокировка?', 'Вместе с завершением всей транзакции', 'При завершении всей транзакции', 'Это верно для остальных блокировок, но не для полученных после точки сохранения.', 'До конца транзакции сохраняются блокировки, полученные до s. Здесь блокировка впервые получена после s и освобождается при откате к этой точке.'),
        ('explanation', 'После SAVEPOINT s транзакция впервые заблокировала строку id = 1 командой UPDATE. Затем выполнила ROLLBACK TO s и осталась открытой. Когда освободится эта блокировка?', NULL, NULL, 'Откат к точке сохранения сразу освобождает обычные блокировки, полученные после её установки.', 'Откат к точке сохранения сразу освобождает блокировки строк и таблиц, полученные после неё.'),
        ('option', 'Две транзакции работают без точек сохранения. A обновила строку 1, B — строку 2, обе открыты. Теперь A обновляет строку 2, а B — строку 1. Что сделает PostgreSQL?', 'Обнаруживает цикл и прерывает одну из транзакций', 'Обнаружит цикл и прервёт одну из них', NULL, NULL),
        ('option', 'Две транзакции работают без точек сохранения. A обновила строку 1, B — строку 2, обе открыты. Теперь A обновляет строку 2, а B — строку 1. Что сделает PostgreSQL?', 'Автоматически фиксирует обе транзакции сразу', 'Прервёт обе конфликтующие транзакции', 'Сервер не фиксирует транзакции вместо приложения для разрешения взаимоблокировки.', 'Для разрыва цикла серверу достаточно прервать одну транзакцию.'),
        ('option', 'Две транзакции работают без точек сохранения. A обновила строку 1, B — строку 2, обе открыты. Теперь A обновляет строку 2, а B — строку 1. Что сделает PostgreSQL?', 'Прерывает ту транзакцию, которая началась позже', 'Прервёт ту транзакцию, что началась позже', NULL, NULL),
        ('option', 'Две транзакции работают без точек сохранения. A обновила строку 1, B — строку 2, обе открыты. Теперь A обновляет строку 2, а B — строку 1. Что сделает PostgreSQL?', 'Обе ждут бесконечно до вмешательства администратора', 'Отменит последние UPDATE обеих транзакций', 'PostgreSQL автоматически обнаруживает взаимоблокировки.', 'Сервер прерывает одну транзакцию целиком, а не отменяет отдельные команды обеих.'),
        ('explanation', 'Строка id = 1 уже зафиксирована. Транзакция A обновила её и осталась открытой. Второй сеанс на Read Committed выполняет по этому id обычный SELECT или UPDATE. Что произойдёт?', NULL, NULL, 'Правило многоверсионности: чтение не блокирует запись, а запись не блокирует чтение. Ждать приходится, когда две транзакции изменяют одну строку, или из-за блокировок таблиц, например при ALTER TABLE.', 'Обычный SELECT читает зафиксированную версию без ожидания блокировки строки, а другой UPDATE ждёт её освобождения. Ждать может и чтение — из-за блокировок таблиц, например при ALTER TABLE.'),
        ('option', 'После BEGIN выполнили SAVEPOINT s и INSERT INTO t VALUES (1). Чей номер записан в xmin новой строки?', 'Номер подтранзакции, а не основной транзакции', 'Номер вставляющей подтранзакции', NULL, NULL),
        ('option', 'После BEGIN выполнили SAVEPOINT s и INSERT INTO t VALUES (1). Чей номер записан в xmin новой строки?', 'Ноль, пока транзакция не зафиксирована', 'Нулевой номер до фиксации транзакции', NULL, NULL),
        ('option', 'После BEGIN выполнили SAVEPOINT s и INSERT INTO t VALUES (1). Чей номер записан в xmin новой строки?', 'Номер основной транзакции без подтранзакции в xmin', 'Номер основной транзакции', 'В xmin записывается номер вставляющей подтранзакции; её связь с основной транзакцией учитывается отдельно.', 'Номер основной транзакции возвращает pg_current_xact_id(), но в xmin записывается номер вставляющей подтранзакции.'),
        ('option', 'Транзакции из вариантов ниже уже завершились. После этого вы на Read Committed выполняете SELECT * FROM t. Какие версии строк вернёт запрос?', 'xmin зафиксирована, xmax равен нулю', 'Вставка зафиксирована, удаления не было', 'Актуальная версия: её никто не удалял и не заменял.', 'Версию вставили и больше не трогали — она актуальна.'),
        ('option', 'Транзакции из вариантов ниже уже завершились. После этого вы на Read Committed выполняете SELECT * FROM t. Какие версии строк вернёт запрос?', 'Транзакции xmin и xmax обе зафиксированы к этому моменту', 'Вставка зафиксирована, удаление зафиксировано', 'Версию удалили или заменили до создания снимка.', 'Удаление зафиксировано до создания снимка, поэтому версия в него не попадёт.'),
        ('option', 'Транзакции из вариантов ниже уже завершились. После этого вы на Read Committed выполняете SELECT * FROM t. Какие версии строк вернёт запрос?', 'Транзакция xmin отменена, версия осталась на странице', 'Вставка отменена, удаления не было', 'Версию создала отменённая транзакция, её как будто не было.', 'Вставку откатили: версия ещё лежит на странице до очистки, но для запросов её как будто не было.'),
        ('option', 'Транзакции из вариантов ниже уже завершились. После этого вы на Read Committed выполняете SELECT * FROM t. Какие версии строк вернёт запрос?', 'xmin зафиксирована, транзакция xmax отменена', 'Вставка зафиксирована, удаление отменено', 'Удаление или изменение отменено, версия остаётся актуальной.', 'Удаление откатили, версия по-прежнему актуальна.'),
        ('explanation', 'Транзакции из вариантов ниже уже завершились. После этого вы на Read Committed выполняете SELECT * FROM t. Какие версии строк вернёт запрос?', NULL, NULL, 'Статус транзакций из xmin и xmax берётся из clog. Версии, созданные отменённой транзакцией, остаются в странице: их пропускают правила видимости, а позже убирает очистка. Если отменено удаление, прежняя версия остаётся видимой.', 'Снимок создан после завершения всех этих транзакций. Видимость решают статусы двух транзакций: создавшей версию (xmin) и удалившей её (xmax); UPDATE для старой версии работает так же, как DELETE. Статусы сервер берёт из pg_xact (clog). Версии отменённых транзакций остаются на странице, пока их не уберёт очистка.'),
        ('option', 'Запрос ждёт блокировку. Что поможет найти блокирующий сеанс или ограничить ожидание?', 'Функция pg_blocking_pids(pid) возвращает номера процессов, блокирующих ожидающий', 'pg_blocking_pids(pid) возвращает PID сеансов, мешающих этому процессу получить блокировку', NULL, NULL),
        ('explanation', 'Запрос ждёт блокировку. Что поможет найти блокирующий сеанс или ограничить ожидание?', NULL, NULL, 'Опыт на двух сеансах: в первом BEGIN; LOCK TABLE t; во втором SET lock_timeout = ''2s''; SELECT * FROM t; — через две секунды ошибка. В третьем: SELECT pid, pg_blocking_pids(pid), wait_event_type FROM pg_stat_activity;', 'Опыт в трёх сеансах с заранее созданной таблицей t. Первый: BEGIN; LOCK TABLE t; Второй: SET lock_timeout = ''30s''; SELECT * FROM t; Пока второй ждёт, третий: SELECT pid, pg_blocking_pids(pid), wait_event_type FROM pg_stat_activity WHERE wait_event_type = ''Lock''; Если первый сеанс держит блокировку и более короткий statement_timeout не сработает, через 30 секунд второй получит ошибку по lock_timeout. В конце в первом сеансе ROLLBACK.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
